rules.cslSource:
csl v4.0 HelloWorldState {
  orgContext GreetingRun { attribute workspace : String required; }
  entity Console {
    attribute name : String required;
    attribute workspace : String required;
    attribute numMsg : Integer required mutable;
  }
}

rules.iStarSource:
istar HelloWorldRequirements {
  role GreetingObserver {
    // Achievement and maintenance remain independent: their status alphabets differ.
    goal TwelveMessagesObserved : Achieve
      condition {[ Console.allInstances()->exists(c | c.workspace = self.workspace and c.numMsg >= 12) ]}
    goal NonnegativeCounts : Maintain
      condition {[ Console.allInstances()->select(c | c.workspace = self.workspace)->notEmpty() and Console.allInstances()->select(c | c.workspace = self.workspace)->forAll(c | c.numMsg >= 0) ]}
  }
}
